        if(tabsState.alliance==='members'){finish(`<div class="alliance-home-list-heading"><strong>${esc(allianceText('member_count',{n:fmt(a.member_count),max:fmt(a.max_members)}))}</strong>${button(esc(allianceText('ranks')),'community-open','members','secondary')}</div><div class="window-list alliance-home-members">${(a.members||[]).map(m=>`<div class="list-row"><button class="text-button member-identity" data-action="public-profile" data-id="${Number(m.player_id)}"><img src="${portrait(m.avatar,m.profile_image)}" alt=""><span><strong data-user-content>${esc(m.display_name)}</strong><small class="alliance-member-rank-summary">${ranks.badge(m.role)}<span>${esc(window.ConquerLocale.t('profile.member_summary',{role:ranks.name(m.role),power:fmt(m.power)}))}</span></small></span></button>${leader&&Number(m.player_id)!==Number(k.profile.id)?button('•••','alliance-member-menu',m.player_id,'secondary small',`aria-label="${esc(allianceText('manage_member',{name:m.display_name}))}"`):''}</div>`).join('')}</div>`);return;}
        if(tabsState.alliance==='treasury'){host().insertAdjacentHTML('beforeend',`<div class="alliance-home-list-heading">${button(esc(allianceText('back_more')),'panel-tab','manage','secondary','data-group="alliance"')}<strong>${esc(allianceText('treasury'))}</strong></div>`);renderTreasury(a,leader);return;}
