        const qs=all.filter(q=>questScope==='main'?q.permanent:!q.permanent),selected=tabsState.quests,visible=qs.filter(q=>selected==='claimed'?q.claimed:selected==='ready'?q.completed&&!q.claimed:!q.claimed).sort((a,b)=>Number(b.completed)-Number(a.completed));
